<title>ブロック崩し</title>
<style>
  * { margin: 0; padding: 0; box-sizing: border-box; }
  body {
    background: #0f0f1a;
    color: #eee;
    font-family: "Segoe UI", "Hiragino Sans", "Meiryo", sans-serif;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    min-height: 100vh;
    user-select: none;
  }
  h1 {
    font-size: 22px;
    letter-spacing: 4px;
    margin-bottom: 10px;
    color: #7fd4ff;
  }
  #hud {
    width: 640px;
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 6px 2px;
    font-size: 15px;
  }
  #hud .label { color: #8899aa; font-size: 12px; margin-right: 6px; }
  #hud .value { font-weight: bold; color: #fff; }
  #lives span { color: #ff6b81; margin-left: 3px; }
