    cursor: none;
  }
  #overlay {
    position: absolute;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: 14px;
    pointer-events: none;
  }
  #overlay.active { pointer-events: auto; }
  #overlay h2 {
    font-size: 34px;
    letter-spacing: 6px;
