</style>
</head>
<body>
<h1>BLOCK BREAKER</h1>
<div id="hud">
  <div><span class="label">SCORE</span><span class="value" id="score">0</span></div>
  <div><span class="label">STAGE</span><span class="value" id="stage">1</span></div>
  <div><span class="label">HI-SCORE</span><span class="value" id="hiscore">0</span></div>
  <div id="lives"><span class="label">LIVES</span></div>
</div>
<div style="position: relative;">
  <canvas id="game" width="640" height="480"></canvas>
  <div id="overlay" class="active" style="inset: 0;">
    <h2 id="overlay-title">ブロック崩し</h2>
    <p id="overlay-msg">マウスまたは ←→ キーでパドルを操作<br>クリック / スペースでボール発射</p>
    <button id="overlay-btn">スタート</button>
  </div>
</div>
<div id="tips">Pキー: 一時停止 &nbsp;|&nbsp; 壊したブロックはステージが進むほど硬くなります</div>

<script>
(() => {
  const canvas = document.getElementById('game');
  const ctx = canvas.getContext('2d');
  const W = canvas.width, H = canvas.height;

  const scoreEl = document.getElementById('score');
  const stageEl = document.getElementById('stage');
  const hiscoreEl = document.getElementById('hiscore');
  const livesEl = document.getElementById('lives');
  const overlay = document.getElementById('overlay');
  const overlayTitle = document.getElementById('overlay-title');
  const overlayMsg = document.getElementById('overlay-msg');
  const overlayBtn = document.getElementById('overlay-btn');

  // ---- 状態 ----
  let score = 0;
  let hiScore = Number(localStorage.getItem('bb-hiscore') || 0);
  let stage = 1;
  let lives = 3;
  let state = 'menu'; // menu | ready | playing | paused | stageclear | gameover | win
  let bricks = [];
  let particles = [];
  let shake = 0;

  const PADDLE_W0 = 100, PADDLE_H = 14, BALL_R = 7;
  const paddle = { x: W / 2 - PADDLE_W0 / 2, y: H - 34, w: PADDLE_W0, speed: 520 };
  const ball = { x: 0, y: 0, vx: 0, vy: 0, r: BALL_R, stuck: true };

  const ROWS = 6, COLS = 10;
  const BRICK_H = 22, GAP = 4, TOP_OFFSET = 50;

  const COLORS = ['#ff6b6b', '#ffa94d', '#ffd43b', '#69db7c', '#4dabf7', '#b197fc'];

  function brickWidth() { return (W - GAP * (COLS + 1)) / COLS; }

  function buildBricks() {
    bricks = [];
    const bw = brickWidth();
    for (let r = 0; r < ROWS; r++) {
      for (let c = 0; c < COLS; c++) {
        // ステージが上がるほど一部が硬くなる
        let hp = 1;
        if (stage >= 2 && r < 2) hp = 2;
        if (stage >= 4 && r < 1) hp = 3;
        bricks.push({
          x: GAP + c * (bw + GAP),
          y: TOP_OFFSET + r * (BRICK_H + GAP),
          w: bw, h: BRICK_H,
          hp, maxHp: hp,
          color: COLORS[r % COLORS.length]
        });
      }
    }
  }

  function resetBall() {
    ball.stuck = true;
    ball.vx = 0; ball.vy = 0;
    ball.x = paddle.x + paddle.w / 2;
    ball.y = paddle.y - ball.r - 1;
  }

  function launchBall() {
    if (!ball.stuck) return;
    const speed = 300 + stage * 25;
    const angle = (-Math.PI / 2) + (Math.random() * 0.7 - 0.35);
    ball.vx = Math.cos(angle) * speed;
    ball.vy = Math.sin(angle) * speed;
    ball.stuck = false;
    state = 'playing';
  }

  function updateHud() {
    scoreEl.textContent = score;
    stageEl.textContent = stage;
    hiscoreEl.textContent = hiScore;
    livesEl.querySelectorAll('span.dot').forEach(e => e.remove());
    for (let i = 0; i < lives; i++) {
      const s = document.createElement('span');
      s.className = 'dot';
      s.textContent = '●';
      livesEl.appendChild(s);
    }
  }

  function showOverlay(title, msg, btnText) {
    overlayTitle.textContent = title;
    overlayMsg.innerHTML = msg;
    overlayBtn.textContent = btnText;
    overlay.classList.remove('hidden');
    overlay.classList.add('active');
  }
  function hideOverlay() {
    overlay.classList.add('hidden');
    overlay.classList.remove('active');
  }

  function startGame() {
    score = 0; stage = 1; lives = 3;
    paddle.w = PADDLE_W0;
    buildBricks();
    resetBall();
    updateHud();
    hideOverlay();
    state = 'ready';
  }

  function nextStage() {
    stage++;
    if (stage > 6) {
      state = 'win';
      saveHiScore();
      showOverlay('CLEAR!', `全ステージ突破おめでとう!<br>SCORE: ${score}`, 'もう一度');
      return;
    }
    paddle.w = Math.max(60, PADDLE_W0 - (stage - 1) * 8);
    buildBricks();
    resetBall();
    updateHud();
    state = 'ready';
  }

  function loseLife() {
    lives--;
    updateHud();
    shake = 8;
    if (lives <= 0) {
      state = 'gameover';
      saveHiScore();
      showOverlay('GAME OVER', `SCORE: ${score}<br>HI-SCORE: ${hiScore}`, 'リトライ');
    } else {
      resetBall();
      state = 'ready';
    }
  }

  function saveHiScore() {
    if (score > hiScore) {
      hiScore = score;
      localStorage.setItem('bb-hiscore', hiScore);
    }
  }

  function spawnParticles(x, y, color) {
    for (let i = 0; i < 10; i++) {
      const a = Math.random() * Math.PI * 2;
      const sp = 60 + Math.random() * 160;
      particles.push({
        x, y,
        vx: Math.cos(a) * sp, vy: Math.sin(a) * sp,
        life: 0.5 + Math.random() * 0.3,
        t: 0,
        color
      });
    }
  }

  function hitBrick(b) {
    b.hp--;
    if (b.hp <= 0) {
      const pts = b.maxHp * 10 * stage;
      score += pts;
      saveHiScore();
      updateHud();
      spawnParticles(b.x + b.w / 2, b.y + b.h / 2, b.color);
      bricks.splice(bricks.indexOf(b), 1);
      if (bricks.length === 0) {
        state = 'stageclear';
        setTimeout(() => {
          if (state === 'stageclear') nextStage();
        }, 900);
      }
    } else {
      spawnParticles(b.x + b.w / 2, b.y + b.h / 2, '#ffffff');
    }
  }

  // ---- 入力 ----
  const keys = {};
  addEventListener('keydown', e => {
    keys[e.code] = true;
    if (e.code === 'Space') {
      e.preventDefault();
      if (state === 'ready') launchBall();
    }
    if (e.code === 'KeyP') {
      if (state === 'playing') state = 'paused';
      else if (state === 'paused') state = 'playing';
    }
  });
  addEventListener('keyup', e => { keys[e.code] = false; });

  canvas.addEventListener('mousemove', e => {
    const rect = canvas.getBoundingClientRect();
    const mx = (e.clientX - rect.left) * (W / rect.width);
    paddle.x = Math.min(Math.max(mx - paddle.w / 2, 0), W - paddle.w);
  });
  canvas.addEventListener('click', () => {
    if (state === 'ready') launchBall();
  });
  overlayBtn.addEventListener('click', () => {
    if (state === 'menu' || state === 'gameover' || state === 'win') startGame();
  });

  // ---- 更新 ----
  function update(dt) {
    if (state === 'playing' || state === 'ready') {
      if (keys['ArrowLeft']) paddle.x -= paddle.speed * dt;
      if (keys['ArrowRight']) paddle.x += paddle.speed * dt;
      paddle.x = Math.min(Math.max(paddle.x, 0), W - paddle.w);
    }
    if (state !== 'playing') return;

    // ボール
    if (ball.stuck) {
      ball.x = paddle.x + paddle.w / 2;
      ball.y = paddle.y - ball.r - 1;
      return;
    }

    ball.x += ball.vx * dt;
    ball.y += ball.vy * dt;

    // 壁
    if (ball.x < ball.r) { ball.x = ball.r; ball.vx = Math.abs(ball.vx); }
    if (ball.x > W - ball.r) { ball.x = W - ball.r; ball.vx = -Math.abs(ball.vx); }
    if (ball.y < ball.r) { ball.y = ball.r; ball.vy = Math.abs(ball.vy); }

    // 床
    if (ball.y > H + ball.r) { loseLife(); return; }

    // パドル
    if (ball.vy > 0 &&
        ball.y + ball.r >= paddle.y && ball.y - ball.r <= paddle.y + PADDLE_H &&
        ball.x >= paddle.x - ball.r && ball.x <= paddle.x + paddle.w + ball.r) {
      const speed = Math.hypot(ball.vx, ball.vy);
      const rel = (ball.x - (paddle.x + paddle.w / 2)) / (paddle.w / 2); // -1..1
      const angle = -Math.PI / 2 + rel * (Math.PI / 3); // 最大60度
      ball.vx = Math.cos(angle) * speed;
      ball.vy = Math.sin(angle) * speed;
      ball.y = paddle.y - ball.r - 0.5;
    }

    // ブロック (AABB + 当たり面判定)
    for (const b of bricks) {
      if (ball.x + ball.r < b.x || ball.x - ball.r > b.x + b.w ||
          ball.y + ball.r < b.y || ball.y - ball.r > b.y + b.h) continue;
      // どの面から入ったかで反射方向を決める
      const overlapX = Math.min(ball.x + ball.r - b.x, b.x + b.w - (ball.x - ball.r));
      const overlapY = Math.min(ball.y + ball.r - b.y, b.y + b.h - (ball.y - ball.r));
      if (overlapX < overlapY) {
        ball.vx = (ball.x < b.x + b.w / 2) ? -Math.abs(ball.vx) : Math.abs(ball.vx);
      } else {
        ball.vy = (ball.y < b.y + b.h / 2) ? -Math.abs(ball.vy) : Math.abs(ball.vy);
      }
      hitBrick(b);
      break;
    }

    // パーティクル
    for (const p of particles) {
      p.t += dt;
      p.x += p.vx * dt;
      p.y += p.vy * dt;
      p.vy += 300 * dt;
    }
    particles = particles.filter(p => p.t < p.life);

    if (shake > 0) shake = Math.max(0, shake - 30 * dt);
  }

  // ---- 描画 ----
  function draw() {
    ctx.save();
    if (shake > 0) {
      ctx.translate((Math.random() - 0.5) * shake, (Math.random() - 0.5) * shake);
    }
    ctx.clearRect(-10, -10, W + 20, H + 20);

    // ブロック
    for (const b of bricks) {
      ctx.globalAlpha = 0.55 + 0.45 * (b.hp / b.maxHp);
      ctx.fillStyle = b.color;
      roundRect(b.x, b.y, b.w, b.h, 4);
      // 光沢
      ctx.globalAlpha = 0.25;
      ctx.fillStyle = '#fff';
      roundRect(b.x + 2, b.y + 2, b.w - 4, 6, 3);
      ctx.globalAlpha = 1;
      if (b.maxHp > 1) {
        ctx.fillStyle = 'rgba(255,255,255,0.85)';
        ctx.font = 'bold 11px sans-serif';
        ctx.textAlign = 'center';
        ctx.fillText(b.hp, b.x + b.w / 2, b.y + b.h / 2 + 4);
      }
    }

    // パドル
    const grad = ctx.createLinearGradient(paddle.x, paddle.y, paddle.x, paddle.y + PADDLE_H);
    grad.addColorStop(0, '#9fd8ff');
    grad.addColorStop(1, '#3a7ab0');
    ctx.fillStyle = grad;
    roundRect(paddle.x, paddle.y, paddle.w, PADDLE_H, 7);

    // ボール
    ctx.fillStyle = '#fff';
    ctx.shadowColor = '#7fd4ff';
    ctx.shadowBlur = 12;
    ctx.beginPath();
    ctx.arc(ball.x, ball.y, ball.r, 0, Math.PI * 2);
    ctx.fill();
    ctx.shadowBlur = 0;

    // パーティクル
    for (const p of particles) {
      ctx.globalAlpha = 1 - p.t / p.life;
      ctx.fillStyle = p.color;
      ctx.fillRect(p.x - 2, p.y - 2, 4, 4);
    }
    ctx.globalAlpha = 1;

    // 一時停止表示
    if (state === 'paused') {
      ctx.fillStyle = 'rgba(0,0,0,0.5)';
      ctx.fillRect(0, 0, W, H);
      ctx.fillStyle = '#fff';
      ctx.font = 'bold 30px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText('PAUSED', W / 2, H / 2);
      ctx.font = '14px sans-serif';
      ctx.fillText('Pキーで再開', W / 2, H / 2 + 30);
    }

    // レディ表示
    if (state === 'ready') {
      ctx.fillStyle = 'rgba(255,255,255,0.7)';
      ctx.font = '14px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText('クリック / スペースで発射', W / 2, H - 70);
    }

    ctx.restore();
  }

  function roundRect(x, y, w, h, r) {
    ctx.beginPath();
    ctx.moveTo(x + r, y);
    ctx.arcTo(x + w, y, x + w, y + h, r);
    ctx.arcTo(x + w, y + h, x, y + h, r);
    ctx.arcTo(x, y + h, x, y, r);
    ctx.arcTo(x, y, x + w, y, r);
    ctx.closePath();
    ctx.fill();
  }

  // ---- メインループ ----
  let last = performance.now();
  function loop(now) {
    const dt = Math.min((now - last) / 1000, 0.033);
    last = now;
    update(dt);
    draw();
    requestAnimationFrame(loop);
  }

  updateHud();
  buildBricks();
  resetBall();
  requestAnimationFrame(loop);
})();
</script>
</body>
</html>
